const https = require('https');
const fs = require('fs');
const url = 'https://bignum-binaries.s3.amazonaws.com/v0.13.0/bignum.node';
https.get(url, (res) => {
  const file = fs.createWriteStream('./build/Release/bignum.node');
  res.pipe(file);
  file.on('finish', () => {
    file.close();
    // Binary ready for loading
